INSERT INTO public."products" ("id", "category_id", "subcategory_id", "brand_id", "name", "gender", "slug", "model_no", "description", "sku", "is_active", "created_at", "updated_at") VALUES
  ('2461b38e-3fb5-4dff-ba38-72206440328d', 'fe79f9fa-f1b3-4512-b97a-ce9b3c887a93', '6f352152-cc9a-446b-a743-18828227995d', 'c3f535eb-1ab9-4b6d-bf8d-49e0ba89b9db', 'Ultima Solid Cotton Trunks for Men - Assorted Colours', 'Men', 'ultima-solid-cotton-trunks-for-men---assorted-colours', 'VP-MI-TR-ULTMC-10P', 'Introducing the VIP Ultima Trunks, made with 100% Combed Cotton fabric for ultimate softness and stretch-ability for an active lifestyle. Featuring a mid-rise fit and a soft outer elasticized waistband that leaves no marks, these trunks offer better durability and comfort. Upgrade your underwear game today!', 'AE-001', 't', '2026-09-12 16:56:49.271798+00', '2026-09-12 16:56:49.271798+00'),
  ('3a9c9ee7-2910-49d2-853a-82f419c61ae6', 'fe79f9fa-f1b3-4512-b97a-ce9b3c887a93', '6f352152-cc9a-446b-a743-18828227995d', 'c3f535eb-1ab9-4b6d-bf8d-49e0ba89b9db', 'Unique   Men''s   Snug   Fit   100%   Cotton   Trunks   -   Assorted   Colours', 'Men', 'unique-mens-snug-fit-100-cotton-trunks---assorted-colours', 'VP-MI-TR-UNICL-10P', 'Discover the ultimate comfort with our VIP Unique Trunks. Made with 100% combed cotton jersey fabric, these trunks feel incredibly soft on your skin. The stretchable mid rise design and contoured double pouch provide a snug fit for better durability. Plus, the tag-free and soft concealed waistband ensures no marks, making them perfect for everyday wear.', 'AE-002', 't', '2026-09-12 17:32:57.877507+00', '2026-09-12 17:32:57.877507+00'),
  ('a4056700-524f-4e88-bbe2-b2ba08db7e5d', 'fe79f9fa-f1b3-4512-b97a-ce9b3c887a93', '6f352152-cc9a-446b-a743-18828227995d', '886928e6-3908-4a0f-b59d-114e374f3c47', 'Plus   Color   Men   100%   Combed   Cotton   Brief   -   Assorted   Color', 'Men', 'plus-color-men-100-combed-cotton-brief---assorted-color', 'FR-MI-BF-PLUSC-10P', 'Experience the difference of 100% combed cotton, smoother than regular cotton, for exceptional comfort against your skin.
